SELECT id, secu_code AS secuCode, secu_name AS secuName FROM ( SELECT id, secu_code, secu_name, update_time, ROW_NUMBER() OVER (PARTITION BY secu_code ORDER BY update_time DESC) AS rn FROM stock_limit_up_record
trade_date > #{dateStr}
) t WHERE rn = 1 ORDER BY secu_code
